 if let part_5::PartNumberRule::Table{rows,..}=&s.part_number_rule{for(n,row)in rows.iter().enumerate(){let id=p.insert("iso16757_part_number_row",&[Cell::Integer(1),ordinal(n)?])?;for(k,(key,value))in row.iter().enumerate(){p.insert("iso16757_part_number_cell",&[Cell::Integer(id),ordinal(k)?,Cell::Text(key),Cell::Text(value)])?;}}}
 for(n,(key,value))in s.part_number_inputs.iter().enumerate(){let value=catalogue_value(p,value)?;p.insert("iso16757_part_number_input",&[Cell::Integer(1),ordinal(n)?,Cell::Text(key),Cell::Integer(value)])?;}
