fn admit_typed(s:&Iso16757Snapshot,c:&mut SqliteSnapshotControl<'_>,phase:SqliteSnapshotPhase)->Result<(),ValueError>{let limits=c.limits();if limits.max_tables<55||limits.max_columns<26{return Err(ValueError::new(ValueRefusalKind::WorkLimit,"ISO authored schema exceeds table or column limit"))}let mut p=Projection::borrowed(c,phase)?;visit(s,&mut p)?;p.finish_borrowed()}
fn project(s:&Iso16757Snapshot,c:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,ValueError>{let mut p=Projection::new(include_str!("🗄️.sql"),c)?;visit(s,&mut p)?;p.finish()}
use std::collections::BTreeMap;
use store::sqlite_snapshot::{SqliteSnapshotPhase,artifact::{FloatRow,reconstruct_text,reconstruct_blob}};
use semio_framework_value::{ValueError, ValueRefusalKind};
fn invalid(message: impl Into<String>) -> ValueError { ValueError::new(ValueRefusalKind::InvalidValue, message) }

type Rows<'a>=BTreeMap<i64,FloatRow<'a>>;
struct Reader<'a>{tables:BTreeMap<&'static str,Rows<'a>>,groups:BTreeMap<(&'static str,i64),Vec<FloatRow<'a>>>}
fn checkpoint(c:&mut SqliteSnapshotControl<'_>,n:usize,total:usize)->Result<(), ValueError>{if n%256==0{c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,n,total)?;}Ok(())}
fn text(r:FloatRow<'_>,i:usize,c:&mut SqliteSnapshotControl<'_>)->Result<String, ValueError>{reconstruct_text(c,r.text(i)?)}
fn optional_text(r:FloatRow<'_>,i:usize,c:&mut SqliteSnapshotControl<'_>)->Result<Option<String>, ValueError>{if r.is_null(i)?{Ok(None)}else{Ok(Some(text(r,i,c)?))}}
fn u32_value(r:FloatRow<'_>,i:usize)->Result<u32, ValueError>{u32::try_from(r.integer(i)?).map_err(|e| invalid(e.to_string()))}
fn optional_u32(r:FloatRow<'_>,i:usize)->Result<Option<u32>, ValueError>{if r.is_null(i)?{Ok(None)}else{Ok(Some(u32_value(r,i)?))}}
fn boolean(r:FloatRow<'_>,i:usize)->Result<bool, ValueError>{match r.integer(i)?{0=>Ok(false),1=>Ok(true),_=>Err(invalid("ISO boolean differs"))}}
fn optional_real(r:FloatRow<'_>,i:usize)->Result<Option<f64>, ValueError>{if r.is_null(i)?{Ok(None)}else{Ok(Some(r.real(i)?))}}
fn active(r:FloatRow<'_>,indices:&[usize])->Result<(), ValueError>{for i in 2..r.values.len(){if !indices.contains(&i)&&!r.is_null(i)?{return Err(invalid("ISO enum inactive field is non-null"));}}Ok(())}
impl<'a> Reader<'a>{
 fn new()->Self{Self{tables:BTreeMap::new(),groups:BTreeMap::new()}}
 fn add(&mut self,d:&'a SqliteDatabase,table:&'static str,count:usize,floats:&'static[FloatColumn],group:bool,c:&mut SqliteSnapshotControl<'_>)->Result<(), ValueError>{let mut rows=Rows::new();for(n,r)in d.table(table)?.rows.iter().enumerate(){checkpoint(c,n,d.table(table)?.rows.len())?;let row=FloatRow::new(r,floats)?;if row.values.len()!=count||row.rowid<=0||row.integer(0)?!=row.rowid||rows.insert(row.rowid,row).is_some(){return Err(invalid("ISO identity or row shape differs"));}if group{let parent=row.integer(1)?;if parent<=0{return Err(invalid("ISO owning parent must be positive"));}self.groups.entry((table,parent)).or_default().push(row);}}self.tables.insert(table,rows);Ok(())}
 fn take(&mut self,table:&'static str,id:i64)->Result<FloatRow<'a>, ValueError>{self.tables.get_mut(table).ok_or_else(|| invalid("ISO missing authored table"))?.remove(&id).ok_or_else(||invalid(format!("ISO {table} reference is missing or multiply owned")))}
 fn ordered(&mut self,table:&'static str,parent:i64,c:&mut SqliteSnapshotControl<'_>)->Result<Vec<FloatRow<'a>>, ValueError>{let rows=self.groups.remove(&(table,parent)).unwrap_or_default();let mut sorted=BTreeMap::new();for(n,r)in rows.into_iter().enumerate(){checkpoint(c,n,0)?;let ordinal=usize::try_from(r.integer(2)?).map_err(|e| invalid(e.to_string()))?;if sorted.insert(ordinal,r).is_some(){return Err(invalid("ISO repeated ordinal"));}}let mut out=Vec::new();for(n,(ordinal,r))in sorted.into_iter().enumerate(){checkpoint(c,n,0)?;if ordinal!=n{return Err(invalid("ISO ordinals must be dense"));}self.take(table,r.rowid)?;out.push(r);}Ok(out)}
 fn finish(&self)->Result<(), ValueError>{if self.tables.values().any(|rows|!rows.is_empty()){return Err(invalid("ISO unowned or dangling entity"));}Ok(())}
}
fn read_names(reader:&mut Reader<'_>,id:i64,c:&mut SqliteSnapshotControl<'_>)->Result<Names, ValueError>{let r=reader.take("iso16757_names",id)?;let mut alternatives=Vec::new();for a in reader.ordered("iso16757_name_alternative",id,c)?{checkpoint(c,alternatives.len(),0)?;alternatives.push(crate::LocalizedText{locale:text(a,3,c)?,text:text(a,4,c)?});}Ok(Names{preferred:crate::LocalizedText{locale:text(r,1,c)?,text:text(r,2,c)?},short_name:optional_text(r,3,c)?,alternatives})}
fn read_unit(reader:&mut Reader<'_>,id:i64,c:&mut SqliteSnapshotControl<'_>)->Result<CatalogueUnit, ValueError>{let r=reader.take("iso16757_unit",id)?;Ok(CatalogueUnit{symbol:text(r,1,c)?,dimension:crate::DimensionSignature{length:i8::try_from(r.integer(2)?).map_err(|e| invalid(e.to_string()))?,mass:i8::try_from(r.integer(3)?).map_err(|e| invalid(e.to_string()))?,time:i8::try_from(r.integer(4)?).map_err(|e| invalid(e.to_string()))?,temperature:i8::try_from(r.integer(5)?).map_err(|e| invalid(e.to_string()))?},si_factor:r.real(6)?})}
fn read_optional_unit(reader:&mut Reader<'_>,r:FloatRow<'_>,i:usize,c:&mut SqliteSnapshotControl<'_>)->Result<Option<CatalogueUnit>, ValueError>{if r.is_null(i)?{Ok(None)}else{Ok(Some(read_unit(reader,r.integer(i)?,c)?))}}
fn retire_values(values:impl IntoIterator<Item=CatalogueValue>){let mut stack:Vec<_>=values.into_iter().collect();while let Some(v)=stack.pop(){if let CatalogueValue::List{items}=v{stack.extend(items);}}}
struct ValueOwners(BTreeMap<i64,CatalogueValue>);
impl Drop for ValueOwners{fn drop(&mut self){retire_values(std::mem::take(&mut self.0).into_values());}}
fn read_value(reader:&mut Reader<'_>,id:i64,c:&mut SqliteSnapshotControl<'_>)->Result<CatalogueValue, ValueError>{enum Step<'a>{Visit(i64),Finish(FloatRow<'a>,Vec<i64>)}let mut stack=vec![Step::Visit(id)];let mut values=ValueOwners(BTreeMap::new());let mut units=0;while let Some(step)=stack.pop(){checkpoint(c,units,0)?;units+=1;match step{Step::Visit(id)=>{let r=reader.take("iso16757_catalogue_value",id)?;let rows=reader.ordered("iso16757_value_element",id,c)?;let mut children=Vec::new();for a in rows{children.push(a.integer(3)?);}if r.text(1)?!="List"&&!children.is_empty(){return Err(invalid("ISO scalar catalogue value owns list elements"));}c.check_rows(stack.len().checked_add(children.len()).ok_or_else(|| ValueError::new(ValueRefusalKind::WorkLimit, "ISO value reconstruction frontier overflow"))?)?;stack.push(Step::Finish(r,children.clone()));for child in children.into_iter().rev(){stack.push(Step::Visit(child));}},Step::Finish(r,children)=>{let kind=r.text(1)?;let value=match kind{"Boolean"=>{active(r,&[2])?;CatalogueValue::Boolean{value:boolean(r,2)?}},"Integer"=>{active(r,&[3])?;CatalogueValue::Integer{value:r.integer(3)?}},"Decimal"=>{active(r,&[4])?;CatalogueValue::Decimal{value:r.real(4)?}},"Text"=>{active(r,&[5])?;CatalogueValue::Text{value:text(r,5,c)?}},"Identifier"=>{active(r,&[5])?;CatalogueValue::Identifier{value:text(r,5,c)?}},"Enumeration"=>{active(r,&[5])?;CatalogueValue::Enumeration{value:text(r,5,c)?}},"Controlled"=>{active(r,&[5,6])?;CatalogueValue::Controlled{value:text(r,5,c)?,list_id:text(r,6,c)?}},"Quantity"=>{active(r,&[4,7])?;CatalogueValue::Quantity{value:r.real(4)?,unit:read_unit(reader,r.integer(7)?,c)?}},"Range"=>{active(r,&[7,8,9])?;CatalogueValue::Range{min:r.real(8)?,max:r.real(9)?,unit:read_optional_unit(reader,r,7,c)?}},"Null"=>{active(r,&[10])?;CatalogueValue::Null{state:match r.text(10)?{"Unavailable"=>NullState::Unavailable,"Unknown"=>NullState::Unknown,"NotApplicable"=>NullState::NotApplicable,_=>return Err(invalid("ISO null state differs"))}}},"Reference"=>{active(r,&[11])?;CatalogueValue::Reference{target_id:text(r,11,c)?}},"List"=>{active(r,&[])?;let mut items=Vec::new();for child in children{items.push(values.0.remove(&child).ok_or_else(|| invalid("ISO incomplete catalogue value tree"))?);}CatalogueValue::List{items}},_=>return Err(invalid("ISO catalogue value kind differs"))};values.0.insert(r.rowid,value);}}}values.0.remove(&id).ok_or_else(|| invalid("ISO value reconstruction missing root"))}
fn retire_nodes(nodes:impl IntoIterator<Item=part_2::GeometryNode>){let mut stack:Vec<_>=nodes.into_iter().collect();while let Some(node)=stack.pop(){match node{part_2::GeometryNode::Transform{child,..}=>stack.push(*child),part_2::GeometryNode::Boolean{children,..}=>stack.extend(children),_=>{}}}}
struct NodeOwners(BTreeMap<i64,part_2::GeometryNode>);
impl Drop for NodeOwners{fn drop(&mut self){retire_nodes(std::mem::take(&mut self.0).into_values());}}
fn read_node(reader:&mut Reader<'_>,id:i64,c:&mut SqliteSnapshotControl<'_>)->Result<part_2::GeometryNode, ValueError>{enum Step<'a>{Visit(i64),Finish(FloatRow<'a>,Vec<i64>)}let mut stack=vec![Step::Visit(id)];let mut nodes=NodeOwners(BTreeMap::new());let mut units=0;while let Some(step)=stack.pop(){checkpoint(c,units,0)?;units+=1;match step{Step::Visit(id)=>{let r=reader.take("iso16757_geometry_node",id)?;let mut children=Vec::new();for a in reader.ordered("iso16757_geometry_child",id,c)?{children.push(a.integer(3)?);}match r.text(1)?{"Transform"=>if children.len()!=1{return Err(invalid("ISO Transform must own exactly one child"));},"Boolean"=>{},"Primitive"|"Reference"=>if !children.is_empty(){return Err(invalid("ISO leaf geometry owns unexpected child"));},_=>return Err(invalid("ISO geometry variant differs"))}c.check_rows(stack.len().checked_add(children.len()).ok_or_else(|| ValueError::new(ValueRefusalKind::WorkLimit, "ISO geometry reconstruction frontier overflow"))?)?;stack.push(Step::Finish(r,children.clone()));for child in children.into_iter().rev(){stack.push(Step::Visit(child));}},Step::Finish(r,children)=>{let parameters=reader.ordered("iso16757_primitive_parameter",r.rowid,c)?;if r.text(1)?!="Primitive"&&!parameters.is_empty(){return Err(invalid("ISO non-primitive geometry owns parameters"));}let node=match r.text(1)?{"Primitive"=>{active(r,&[2])?;let mut map=BTreeMap::new();for a in parameters{if map.insert(text(a,3,c)?,a.real(4)?).is_some(){return Err(invalid("ISO repeated primitive parameter key"));}}part_2::GeometryNode::Primitive{kind:text(r,2,c)?,parameters:map}},"Transform"=>{active(r,&[5,6,7,8,9,10])?;part_2::GeometryNode::Transform{translation:[r.real(5)?,r.real(6)?,r.real(7)?],rotation_deg:[r.real(8)?,r.real(9)?,r.real(10)?],child:Box::new(nodes.0.remove(&children[0]).ok_or_else(|| invalid("ISO incomplete Transform child"))?)}},"Boolean"=>{active(r,&[3])?;let operator=match r.text(3)?{"Union"=>part_2::BooleanOperator::Union,"Intersection"=>part_2::BooleanOperator::Intersection,"Difference"=>part_2::BooleanOperator::Difference,_=>return Err(invalid("ISO CSG operator differs"))};let mut values=Vec::new();for child in children{values.push(nodes.0.remove(&child).ok_or_else(|| invalid("ISO incomplete Boolean child"))?);}part_2::GeometryNode::Boolean{operator,children:values}},"Reference"=>{active(r,&[4])?;part_2::GeometryNode::Reference{geometry_id:text(r,4,c)?}},_=>return Err(invalid("ISO geometry kind differs"))};nodes.0.insert(r.rowid,node);}}}nodes.0.remove(&id).ok_or_else(|| invalid("ISO geometry reconstruction missing root"))}
fn retire_extensions(values:impl IntoIterator<Item=semio_framework_value::DslValue>){let mut stack:Vec<_>=values.into_iter().collect();while let Some(value)=stack.pop(){match value{semio_framework_value::DslValue::Array(items)=>stack.extend(items),semio_framework_value::DslValue::Object(items)=>stack.extend(items.into_iter().map(|(_,value)|value)),_=>{}}}}
struct ExtensionOwners(BTreeMap<i64,semio_framework_value::DslValue>);
impl Drop for ExtensionOwners{fn drop(&mut self){retire_extensions(std::mem::take(&mut self.0).into_values());}}
fn read_extension(reader:&mut Reader<'_>,id:i64,c:&mut SqliteSnapshotControl<'_>)->Result<semio_framework_value::DslValue, ValueError>{enum Step<'a>{Visit(i64),Finish(FloatRow<'a>,Vec<(Option<String>,i64)>)}let mut stack=vec![Step::Visit(id)];let mut values=ExtensionOwners(BTreeMap::new());let mut units=0;while let Some(step)=stack.pop(){checkpoint(c,units,0)?;units+=1;match step{Step::Visit(id)=>{let r=reader.take("iso16757_extension_value",id)?;let elements=reader.ordered("iso16757_extension_element",id,c)?;let members=reader.ordered("iso16757_extension_member",id,c)?;let mut children=Vec::new();match r.text(1)?{"Array"=>{if !members.is_empty(){return Err(invalid("ISO extension Array owns members"));}for a in elements{children.push((None,a.integer(3)?));}},"Object"=>{if !elements.is_empty(){return Err(invalid("ISO extension Object owns elements"));}for a in members{children.push((Some(text(a,3,c)?),a.integer(4)?));}},_=>if !elements.is_empty()||!members.is_empty(){return Err(invalid("ISO extension scalar owns children"));}}c.check_rows(stack.len().checked_add(children.len()).ok_or_else(|| ValueError::new(ValueRefusalKind::WorkLimit, "ISO extension reconstruction frontier overflow"))?)?;let ids:Vec<_>=children.iter().map(|(_,id)|*id).collect();stack.push(Step::Finish(r,children));for child in ids.into_iter().rev(){stack.push(Step::Visit(child));}},Step::Finish(r,children)=>{let value=match r.text(1)?{"Null"=>{active(r,&[])?;semio_framework_value::DslValue::Null},"Boolean"=>{active(r,&[2])?;semio_framework_value::DslValue::Bool(boolean(r,2)?)},"Integer"=>{active(r,&[3])?;semio_framework_value::DslValue::Number(semio_framework_value::Number::Int(r.integer(3)?))},"Unsigned"=>{active(r,&[4,5])?;semio_framework_value::DslValue::Number(semio_framework_value::Number::UInt((u64::from(u32_value(r,4)?)<<32)|u64::from(u32_value(r,5)?)))},"Float"=>{active(r,&[6])?;semio_framework_value::DslValue::Number(semio_framework_value::Number::Float(r.real(6)?))},"Text"=>{active(r,&[7])?;semio_framework_value::DslValue::String(text(r,7,c)?)},"Bytes"=>{active(r,&[8])?;semio_framework_value::DslValue::Bytes(reconstruct_blob(c,r.blob(8)?)?)},"Array"=>{active(r,&[])?;let mut items=Vec::new();for(_,id)in children{items.push(values.0.remove(&id).ok_or_else(|| invalid("ISO incomplete extension Array"))?);}semio_framework_value::DslValue::Array(items)},"Object"=>{active(r,&[])?;let mut members=Vec::new();for(key,id)in children{members.push((key.ok_or_else(|| invalid("ISO extension member key missing"))?,values.0.remove(&id).ok_or_else(|| invalid("ISO incomplete extension Object"))?));}semio_framework_value::DslValue::Object(members)},_=>return Err(invalid("ISO extension kind differs"))};values.0.insert(r.rowid,value);}}}values.0.remove(&id).ok_or_else(|| invalid("ISO extension reconstruction missing root"))}
fn reader<'a>(d:&'a SqliteDatabase,c:&mut SqliteSnapshotControl<'_>)->Result<Reader<'a>, ValueError>{let mut r=Reader::new();r.add(d,"iso16757_document",26,&[],false,c)?;r.add(d,"iso16757_names",4,&[],false,c)?;r.add(d,"iso16757_name_alternative",5,&[],true,c)?;r.add(d,"iso16757_unit",7,UNIT,false,c)?;r.add(d,"iso16757_catalogue_value",12,VALUE,false,c)?;r.add(d,"iso16757_value_element",4,&[],true,c)?;r.add(d,"iso16757_product_group",6,&[],true,c)?;r.add(d,"iso16757_product_class",7,&[],true,c)?;r.add(d,"iso16757_class_required_property",4,&[],true,c)?;r.add(d,"iso16757_class_optional_property",4,&[],true,c)?;r.add(d,"iso16757_product_series",7,&[],true,c)?;r.add(d,"iso16757_series_property",5,&[],true,c)?;r.add(d,"iso16757_product",6,&[],true,c)?;r.add(d,"iso16757_parameter_domain",5,&[],true,c)?;r.add(d,"iso16757_domain_allowed_value",4,&[],true,c)?;r.add(d,"iso16757_product_variant",6,&[],true,c)?;r.add(d,"iso16757_variant_parameter",5,&[],true,c)?;r.add(d,"iso16757_property_value",4,&[],false,c)?;r.add(d,"iso16757_variant_property",4,&[],true,c)?;r.add(d,"iso16757_product_static_property",4,&[],true,c)?;r.add(d,"iso16757_product_index",6,&[],true,c)?;r.add(d,"iso16757_index_tag",4,&[],true,c)?;r.add(d,"iso16757_property_definition",11,&[],true,c)?;r.add(d,"iso16757_accessory_group",4,&[],true,c)?;r.add(d,"iso16757_accessory",8,&[],true,c)?;r.add(d,"iso16757_composition_group",4,&[],true,c)?;r.add(d,"iso16757_composition",5,&[],true,c)?;r.add(d,"iso16757_descriptive_object",8,&[],true,c)?;r.add(d,"iso16757_dictionary_subject",10,&[],false,c)?;r.add(d,"iso16757_dictionary_relationship",9,&[],true,c)?;r.add(d,"iso16757_dictionary_property",8,&[],true,c)?;r.add(d,"iso16757_property_subject",4,&[],true,c)?;r.add(d,"iso16757_value_constraint",5,CONSTRAINT,true,c)?;r.add(d,"iso16757_constraint_allowed",4,&[],true,c)?;r.add(d,"iso16757_controlled_list",4,&[],true,c)?;r.add(d,"iso16757_controlled_value",4,&[],true,c)?;r.add(d,"iso16757_controlled_context",4,&[],true,c)?;r.add(d,"iso16757_geometry_object",7,&[],true,c)?;r.add(d,"iso16757_geometry_node",11,NODE,false,c)?;r.add(d,"iso16757_geometry_child",4,&[],true,c)?;r.add(d,"iso16757_primitive_parameter",5,PARAMETER,true,c)?;r.add(d,"iso16757_space",11,BOUNDS,true,c)?;r.add(d,"iso16757_surface",11,BOUNDS,true,c)?;r.add(d,"iso16757_port",12,BOUNDS,true,c)?;r.add(d,"iso16757_geometry_binding",5,&[],true,c)?;r.add(d,"iso16757_primitive_kind",4,&[],true,c)?;r.add(d,"iso16757_primitive_kind_parameter",4,&[],true,c)?;r.add(d,"iso16757_selection_constraint",7,&[],true,c)?;r.add(d,"iso16757_part_number_row",3,&[],true,c)?;r.add(d,"iso16757_part_number_cell",5,&[],true,c)?;r.add(d,"iso16757_part_number_input",5,&[],true,c)?;r.add(d,"iso16757_extension_entry",5,&[],true,c)?;r.add(d,"iso16757_extension_value",9,EXTENSION,false,c)?;r.add(d,"iso16757_extension_element",4,&[],true,c)?;r.add(d,"iso16757_extension_member",5,&[],true,c)?;Ok(r)}
