fn retire_snapshot(mut s:Iso16757Snapshot){let mut values=Vec::new();for v in s.catalogue.product_series.drain(..){values.extend(v.shared_property_values.into_values());}for v in s.catalogue.products.drain(..){for domain in v.parameter_domains{values.extend(domain.allowed_values);values.extend(domain.default_value);}for variant in v.variants{values.extend(variant.parameter_values.into_values());values.extend(variant.property_values.into_iter().map(|v|v.value));}values.extend(v.static_properties.into_iter().map(|v|v.value));}values.extend(s.selection.constraints.drain(..).map(|v|v.value));values.extend(std::mem::take(&mut s.part_number_inputs).into_values());retire_values(values);let mut nodes=Vec::new();for(_,v)in std::mem::take(&mut s.geometry.objects){nodes.extend(v.shape);nodes.extend(v.symbolic);}retire_nodes(nodes);retire_extensions(std::mem::take(&mut s.catalogue.extensions.fields).into_values());}
